mapper.select:
select count(1)
from category
where parent_id = #{parentId}
  and name = #{name}

select count(1)
from category
where parent_id = #{parentId}
  and name = #{name}
  and id != #{id}

select c.id, c.parent_id, c.name, c.level, c.sort, c.status, coalesce(g.goods_count, 0) as goods_count, c.create_time, c.update_time from category c left join ( select category_id, count(1) as goods_count from goods group by category_id ) g on c.id = g.category_id
and c.name like concat('%', #{name}, '%')
and c.parent_id = #{parentId}
and c.status = #{status}
order by c.level asc, c.sort asc, c.id asc

select count(1)
from category
where parent_id = #{parentId}

select count(1)
from goods
where category_id = #{categoryId}
